        old_setting->it_interval = timr->it_interval;
        old_setting->it_value = timr->it_value;
    }

    timr->it_interval.tv_sec = 0;
    timr->it_interval.tv_nsec = 0;

    if (timr->active) {
        int result = timer_delete(timr);
        if (result == TIMER_RETRY) {
            return TIMER_RETRY;
        }
    }

    if (new_setting->it_value.tv_sec == 0 && new_setting->it_value.tv_nsec == 0) {
